from pathlib import Path
import json, html, base64, re
R=Path(__file__).parent;D=json.loads((R/'episode_01.json').read_text());OUT=R.parent
def e(s):return html.escape(str(s),quote=True)
def tc(s):return f'{int(s)//60:02d}:{int(s)%60:02d}'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff8ea;color:#16332c;font:17px/1.65 system-ui,Arial,sans-serif}main{max-width:1180px;margin:auto;padding:42px 30px 100px}h1{font-size:clamp(34px,5vw,64px);line-height:1.08;letter-spacing:-.04em;margin:15px 0 25px}h2{font-size:32px;margin:60px 0 20px}h3{font-size:23px;line-height:1.3;margin:26px 0 12px}h4{margin:18px 0 5px}p{margin:10px 0 17px}a{color:#176b56}nav{display:flex;flex-wrap:wrap;gap:10px 22px;padding:18px 0;border-top:1px solid #c6d6ca;border-bottom:1px solid #c6d6ca}nav a{text-decoration:none;font-weight:650}.kicker{font-size:13px;font-weight:750;letter-spacing:.14em;text-transform:uppercase;color:#29745d}.badge{display:inline-block;border-radius:18px;padding:5px 13px;background:#d9ebdf;font-weight:650;font-size:14px}.notice{border-left:5px solid #d97528;background:#fff0d4;padding:18px 22px;margin:25px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.castgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card,.shot,.lesson{background:#fffdf7;border:1px solid #d8dfd2;border-radius:18px;padding:22px;margin:18px 0}.card p{font-size:16px}.lesson{background:#e7f0e7}.timeline{border-top:3px solid #29745d;margin-top:35px;padding-top:10px}.time{font:650 15px ui-monospace,monospace;color:#29745d}.line{margin:10px 0;padding-left:16px;border-left:3px solid #c3d7cb}.line strong{font-size:14px;color:#29745d}figure{margin:18px 0}img{display:block;width:100%;height:auto;border-radius:13px}.portrait{max-height:440px;object-fit:contain}figcaption,.small{font-size:14px;color:#526b60}table{border-collapse:collapse;width:100%;font-size:15px}th,td{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #d7ded0}th{background:#e7efe5}details{margin:15px 0}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;background:#ecf0e8;padding:20px;overflow-wrap:anywhere;font:14px/1.5 ui-monospace,monospace}code{font-size:.9em}footer{margin-top:60px;border-top:2px solid #29745d;padding-top:25px}.toc{display:flex;gap:8px;flex-wrap:wrap}.toc a{background:#e2ebdf;padding:5px 10px;border-radius:8px;text-decoration:none}.status{color:#805217}@media(max-width:740px){main{padding:25px 18px}.grid,.castgrid{grid-template-columns:1fr}h2{font-size:27px}table{font-size:13px}th,td{padding:7px}}@media print{body{background:white}nav,.toc,summary{display:none}main{max-width:none;padding:0}.shot,.lesson,figure{break-inside:avoid}details{display:none}a{color:inherit;text-decoration:none}h2{break-before:page}.timeline{break-before:page}img{max-height:500px;object-fit:contain}}'''
def build(lite=False):
 def image(path,caption='',cls=''):
  p=R/path
  if not p.exists():return '<p class="status">Asset not generated: '+e(path)+'</p>'
  src='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() if lite else path
  return f'<figure><img class="{cls}" src="{src}" loading="lazy" alt="{e(caption)}"><figcaption>{e(caption)}</figcaption></figure>'
 b=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Maple House English — Episode 1 Production Book</title><style>'+CSS+'</style></head><body><main>',
 '<div class="kicker">Original family comedy • American English</div><h1>Maple House English</h1><p style="font-size:26px">Two Lists, One Dad<br>The Vegetable Market Mix-Up</p><span class="badge">20:00 planned runtime</span> <span class="badge">48 story clips + 24 recaps</span>',
 '<div class="notice"><strong>Preproduction delivery.</strong> The complete script and production assets are prepared. Task 5 is deferred by your instruction: no Flow video, performed voice, lip-sync or finished episode has been generated. Six illustrated boards exist; later illustrated-board generation was interrupted. All 48 shots have reference production cards.</div>',
 '<nav><a href="#plan">First 10 uploads</a><a href="#cast">Permanent family</a><a href="#world">Visual world</a><a href="#episode">Complete episode</a><a href="#workflow">Original 22 sections</a><a href="#handoff">Next production stage</a></nav>',
 '<h2 id="plan">The first 10 uploads</h2><p>Publication order builds familiar words, locations and relationships gradually. Every episode uses 24 cycles of 30 seconds of story plus a 20-second recap. Build a finished-episode buffer before promising daily uploads.</p>']
 b.append('<table><thead><tr><th>Day</th><th>Episode / hook</th><th>Main learning</th></tr></thead><tbody>')
 for q in D['episodes']:b.append(f'<tr><td>{q["day"]}</td><td><strong>{e(q["title"])}</strong><br>{e(q["hook"])}</td><td>{e(q["vocabulary"])}</td></tr>')
 b.append('</tbody></table>')
 for q in D['episodes']:
  b.append(f'<details><summary>Episode {q["day"]}: story, grammar and publication design</summary><p>{e(q["story"])}</p><p><strong>Arc:</strong> {e(q["arc"])}</p><p><strong>Grammar:</strong> {e(q["grammar"])}</p><p><strong>Pronunciation:</strong> {e(q["pronunciation"])}</p><p><strong>Relative appearance:</strong> {e(q["relative"])}</p></details>')
 b+=['<h2 id="cast">One permanent family</h2><p>Dan is married to Maya and Nina. Maya is Leo and Ella’s mother; Nina is Max’s mother. The adults are equal, affectionate partners. Comedy comes from misunderstandings and repair, not jealousy or humiliation.</p>',image('characters/ADULTS_LINEUP_v01.png','Dan • Maya • Nina — selected v1 designs'),image('characters/CHILDREN_LINEUP_v01.png','Leo • Ella • Max — selected v1 designs'),'<div class="castgrid">']
 for c in D['cast']:
  b.append('<section class="card"><h3>'+e(c['name'])+'</h3><p><strong>'+str(c['age'])+' years • design height '+str(c['height_cm'])+' cm</strong></p>')
  if not lite:b.append(image(f'characters/{c["id"]}_ID_v01.png',c['id']+' individual master','portrait'))
  b.append('<p>'+e(c['personality'])+'</p><p><strong>Identity:</strong> '+e(c['identity'])+'</p><p>'+e(c['outfit'])+'</p><p><strong>Voice brief:</strong> '+e(c['voice'])+'</p>')
  if not lite:b.append('<details><summary>Views and expressions</summary>'+image(f'characters/{c["id"]}_SHEET_v01.png',c['id']+' reference sheet')+'</details>')
  b.append('</section>')
 b.append('</div><p class="small">These are selected v1 raster references, not rigged 3D models or a guarantee of identical generated motion. Actual saved voice IDs remain uncreated. Never silently accept a different face as a new normal.</p>')
 b+=['<h2 id="world">The visual world</h2>',image('environments/MARKET_WIDE_v01.png','Maple Falls market — fixed morning setting')]
 if not lite:
  for k,v in D['environments'].items():
   if k!='MARKET_WIDE':b.append('<details><summary>'+e(k)+'</summary>'+image(v['image'],v['layout'])+'<p>'+e(v['camera_axis'])+'</p></details>')
  b.append(image('environments/HOME_TABLE_seating.png','Canonical dining-room seating'))
 b+=['<h3>Two lists. Exact quantities.</h3><div class="grid"><section class="card"><h4>Maya’s BLUE salad list</h4><p>4 carrots • 3 tomatoes • 1 cucumber • 1 loose-leaf lettuce • 1 red bell pepper</p><strong>$9.00</strong></section><section class="card"><h4>Nina’s YELLOW soup list</h4><p>6 potatoes • 2 onions • 1 head of broccoli • 2 ears of corn • 1 bag of spinach</p><strong>$9.50</strong></section></div><p>Total $18.50; payment $20.00; change $1.50. These are fictional story prices. Zucchini and cabbage are examined and returned, never purchased.</p>',
 '<h3>Illustration and exact editorial graphics</h3>',image('storyboards/BOARD_01.png','Illustrated storyboard study, S01–S04 — planning art, not a generated video'),image('learning/cards/R04.png','Example recap overview — final playback uses separate reveal phases'),
 '<p>The six illustrated sheets cover S01–S24. Known quantity and geography differences are logged in the package; they are not approved animation start frames. All 48 reference-based shot cards use the canonical inputs and exact written state. Recap text, lists, prices and quantity inserts are rendered from editable SVG layouts.</p>',
 '<h2 id="episode">Complete episode: 00:00–20:00</h2><p>Each cycle is 50 seconds: 15 + 15 seconds of story, then 20 seconds of learning. During every recap, the learner speaks from second 11 through second 16. Title and end-card overlays fit inside the planned slots.</p><p class="small">Speech windows below are planned, not measured performances. The full Markdown script and SRT contain cue-level timestamps. Story actions, references, inventory and acceptance criteria are also in each individual Flow prompt.</p><div class="toc">']
 for i in range(1,25):b.append(f'<a href="#cycle{i}">{i:02d}</a>')
 b.append('</div>')
 for i in range(24):
  shots=D['shots'][i*2:i*2+2];r=D['recaps'][i]
  b.append(f'<article class="timeline" id="cycle{i+1}"><div class="time">{tc(i*50)}–{tc((i+1)*50)} • CYCLE {i+1:02d}</div><h3>{e(shots[0]["title"])}</h3>')
  for s in shots:
   b.append('<section class="shot"><div class="time">'+s['id']+' • '+tc(s['start'])+'–'+tc(s['end'])+' • 15 seconds</div><p><strong>Cast / setting:</strong> '+e(', '.join(s['cast'])+' / '+s['location'])+'</p>')
   for ln in s['dialogue_cues']:
    b.append('<p class="line"><strong>'+e(ln['speaker'])+' • '+f'{ln["start"]-s["start"]:.2f}–{ln["end"]-s["start"]:.2f}s'+'</strong><br>'+e(ln['text'])+'</p>')
   b.append('<p><strong>Action:</strong> '+e(s['action'])+'</p><p><strong>Camera:</strong> '+e(s['camera'])+'</p><p><strong>Start:</strong> '+e(s['start_state'])+'</p><p><strong>End:</strong> '+e(s['end_state'])+'</p>')
   b.append('<details><summary>Exact inventory and production prompt</summary><p>'+e(s['inventory_note'])+'</p><pre>'+e(s['flow_prompt'])+'</pre>')
   if not lite:b.append(image(s['storyboard'],s['id']+' reference-based production card'))
   b.append('</details></section>')
  b.append('<section class="lesson"><div class="time">'+r['id']+' • '+tc(r['start'])+'–'+tc(r['end'])+' • 20 seconds</div><h4>'+e(r['word'])+'</h4><p><strong>Pronunciation:</strong> '+e(r['pronunciation'])+'<br><strong>Sentence:</strong> '+e(r['example'])+'<br><strong>Grammar:</strong> '+e(r['rule'])+'<br><strong>Level:</strong> '+e(r['level'])+'</p>')
  for k,ln in enumerate(r['narration_cues']):
   if k==3:b.append('<p class="line"><strong>'+tc(r['speaking_pause']['start'])+'–'+tc(r['speaking_pause']['end'])+'</strong><br>VIEWER SPEAKS — five seconds of silence; answer hidden.</p>')
   b.append('<p class="line"><strong>'+tc(ln['start'])+'–'+tc(ln['end'])+' • NARRATOR</strong><br>'+e(ln['text'])+'</p>')
  b.append('<p><strong>Speaking task:</strong> '+e(r['prompt'])+'<br><strong>Model answer:</strong> '+e(r['answer'])+'</p>')
  if r['extension']:b.append('<p><strong>Optional extension / edit note:</strong> '+e(r['extension'])+'</p>')
  if not lite:b.append('<details><summary>Recap design</summary>'+image(f'learning/cards/{r["id"]}.png',r['id']+' editor overview; use phase files for timed reveal')+'</details>')
  b.append('</section></article>')
 b+=['<h2 id="workflow">The original 22 sections, applied</h2><p>The original guide was retrieved from the existing conversation document. It contains 22 numbered sections; the exact headings are retained below. Generation-dependent work is prepared or deferred, rather than falsely marked executed.</p><p><a href="https://chatgpt.com/library?file_id=libfile_fe6b1d8961b08191ad877e58a6cf81f8&amp;account_id=personal">Original Google Flow Feature Film Production Guide</a></p><table><thead><tr><th>No.</th><th>Original section</th><th>Episode 1 application</th></tr></thead><tbody>']
 status=['20-minute scope and exact timing','Requested configuration recorded; UI verification deferred','Complete original script','Visual language and palette','Six selected character masters','Six sheets and two lineups','Actor and voice setup deferred','Five environment masters','48-shot ledger and explicit inventories','48 reference cards; 24 illustrated panels; animatic deferred','Mode and reference strategy prepared','48 individual prompts','100-second pilot specification','Data checks run; motion/voice gates pending','Batch plan and pending acceptance log','Voice briefs and cue scripts; no audio','Edit/reveal/export specification; no film','Historical-rate scenarios; actual Flow spend zero','Gate-based schedule and recovery rules','Populated cast and continuity records','Shot acceptance records prepared','Pilot and launch deferred by user']
 for i,((h,t),s) in enumerate(zip(D['original_22_sections'],status),1):b.append(f'<tr><td>{i:02d}</td><td><strong>{e(h)}</strong><br>{e(t)}</td><td>{e(s)}</td></tr>')
 b+=['</tbody></table><h2 id="handoff">What is ready, and what comes next</h2><p>Ready: all creative writing, selected visual identities, references, exact educational graphics, timed phase images, prompts and production records. Still pending: later cinematic storyboard illustrations, approved shot-specific first frames, actual saved voices, the pilot, Flow clips, lip-sync, final audio/edit/export and upload.</p><p>The next production session begins with the 100-second pilot, using S01–S04 and R01–R02. Preserve the 20-minute edit map and reuse these same identities. Verify the actual signed-in Flow model, duration options and credit quote before generation. The requested model name is carried over from your brief, not freshly verified here.</p><footer><strong>Files to keep:</strong> original masters, cast bible, environment references, episode_01.json, continuity ledger, phase_manifest.json, prompts and acceptance log. The package README explains every folder. No footage has been fabricated or labeled as complete.</footer></main></body></html>']
 return ''.join(b)
(R/'Episode_01_Production_Book.html').write_text(build(False))
(OUT/'Maple_House_Episode_01_Review.html').write_text(build(True))
print('Built portable project book and self-contained text review with selected images.')
